-- API keys of client applications (spec §6.16, SA_6 §2.1.6). A key is a public 8-character prefix (unique across
-- organizations: a request carries only the prefix) plus a secret whose scrypt hash is stored (secret_hash: writable
-- by the backend, never selectable). The plaintext is generated by the backend action rotate_client_key and returned
-- once; store_client_key (admin only) persists it. At most two active keys per application (rotation overlap);
-- revoke_client_key (org_admin) retires one. Keys are immutable except the one-way revocation (flag
-- itap.client_key_context) and last_used_at (system write by the key auth middleware).
CREATE TABLE itap.client_application_keys (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES itap.organizations (id) ON DELETE CASCADE,
  application_id uuid NOT NULL,
  key_prefix text NOT NULL,
  secret_hash text NOT NULL,
  created_by uuid,
  expires_at timestamptz,
  revoked_at timestamptz,
  revoked_by uuid,
  last_used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT client_application_keys_organization_id_id_key UNIQUE (organization_id, id),
  CONSTRAINT client_application_keys_key_prefix_key UNIQUE (key_prefix),
  CONSTRAINT client_application_keys_prefix_format CHECK (key_prefix ~ '^[A-Za-z0-9]{8}$'),
  CONSTRAINT client_application_keys_secret_hash_not_blank CHECK (btrim(secret_hash) <> ''),
  CONSTRAINT client_application_keys_revoked_consistent CHECK (revoked_at IS NOT NULL OR revoked_by IS NULL),
  CONSTRAINT client_application_keys_application_fkey FOREIGN KEY (organization_id, application_id)
    REFERENCES itap.client_applications (organization_id, id) ON DELETE CASCADE,
  CONSTRAINT client_application_keys_created_by_fkey FOREIGN KEY (organization_id, created_by)
    REFERENCES itap.organization_members (organization_id, user_id) ON DELETE NO ACTION,
  CONSTRAINT client_application_keys_revoked_by_fkey FOREIGN KEY (organization_id, revoked_by)
    REFERENCES itap.organization_members (organization_id, user_id) ON DELETE NO ACTION
);
CREATE INDEX client_application_keys_organization_id_application_id_idx
  ON itap.client_application_keys (organization_id, application_id);
CREATE INDEX client_application_keys_organization_id_created_by_idx ON itap.client_application_keys (organization_id, created_by);
CREATE INDEX client_application_keys_organization_id_revoked_by_idx ON itap.client_application_keys (organization_id, revoked_by);

CREATE FUNCTION itap.guard_client_application_key() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, itap
AS $$
DECLARE
  in_revoke boolean := coalesce(current_setting('itap.client_key_context', true), '') = 'on';
  free text[] := ARRAY['revoked_at', 'revoked_by', 'last_used_at', 'updated_at'];
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.revoked_at IS NOT NULL OR NEW.last_used_at IS NOT NULL THEN
      PERFORM itap.raise_code('client_key_not_editable');
    END IF;
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - free) IS DISTINCT FROM (to_jsonb(OLD) - free)
     OR ((NEW.revoked_at, NEW.revoked_by) IS DISTINCT FROM (OLD.revoked_at, OLD.revoked_by)
         AND (NOT in_revoke OR OLD.revoked_at IS NOT NULL)) THEN
    PERFORM itap.raise_code('client_key_not_editable');
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER client_application_keys_guard BEFORE INSERT OR UPDATE ON itap.client_application_keys
  FOR EACH ROW EXECUTE FUNCTION itap.guard_client_application_key();
CREATE TRIGGER client_application_keys_set_updated_at BEFORE UPDATE ON itap.client_application_keys
  FOR EACH ROW EXECUTE FUNCTION itap.set_updated_at_except('last_used_at');
-- secret_hash redacted; last_used_at is a frequent system write, not audited.
CREATE TRIGGER audit AFTER INSERT OR UPDATE OR DELETE ON itap.client_application_keys
  FOR EACH ROW EXECUTE FUNCTION itap.audit_row_change('secret_hash', 'ignore:last_used_at');

-- Admin only (called by the backend action rotate_client_key with the caller's session): stores a new key for an
-- application of the session organization. The caller must be an active member; the application must not be
-- revoked; at most two active (not revoked, not expired) keys per application.
CREATE FUNCTION itap.store_client_key(
  hasura_session json,
  p_application uuid,
  p_key_prefix text,
  p_secret_hash text,
  p_expires_at timestamptz DEFAULT NULL
) RETURNS SETOF itap.client_application_keys
LANGUAGE plpgsql VOLATILE
SET search_path = pg_catalog, itap
AS $$
DECLARE
  org uuid := itap.session_organization(hasura_session);
  actor uuid := itap.require_active_member(hasura_session);
  app_status text;
  new_id uuid;
BEGIN
  SELECT status INTO app_status FROM itap.client_applications
  WHERE organization_id = org AND id = p_application FOR UPDATE;
  IF NOT FOUND THEN
    PERFORM itap.raise_code('client_application_not_found');
  END IF;
  IF app_status = 'revoked' THEN
    PERFORM itap.raise_code('client_application_revoked');
  END IF;
  IF p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    PERFORM itap.raise_code('client_key_expiry_invalid');
  END IF;
  IF (SELECT count(*) FROM itap.client_application_keys k
      WHERE k.organization_id = org AND k.application_id = p_application
        AND k.revoked_at IS NULL AND (k.expires_at IS NULL OR k.expires_at > now())) >= 2 THEN
    PERFORM itap.raise_code('client_key_limit');
  END IF;
  INSERT INTO itap.client_application_keys (organization_id, application_id, key_prefix, secret_hash, created_by, expires_at)
  VALUES (org, p_application, p_key_prefix, p_secret_hash, actor, p_expires_at)
  RETURNING id INTO new_id;
  RETURN QUERY SELECT * FROM itap.client_application_keys WHERE id = new_id;
END;
$$;

-- Tracked mutation (org_admin, active member): revokes a key once.
CREATE FUNCTION itap.revoke_client_key(hasura_session json, p_key uuid)
RETURNS SETOF itap.client_application_keys
LANGUAGE plpgsql VOLATILE
SET search_path = pg_catalog, itap
AS $$
DECLARE
  org uuid := itap.session_organization(hasura_session);
  actor uuid := itap.require_active_member(hasura_session);
  revoked timestamptz;
BEGIN
  SELECT revoked_at INTO revoked FROM itap.client_application_keys WHERE organization_id = org AND id = p_key FOR UPDATE;
  IF NOT FOUND THEN
    PERFORM itap.raise_code('client_key_not_found');
  END IF;
  IF revoked IS NOT NULL THEN
    PERFORM itap.raise_code('client_key_revoked');
  END IF;
  PERFORM set_config('itap.client_key_context', 'on', true);
  UPDATE itap.client_application_keys SET revoked_at = now(), revoked_by = actor WHERE organization_id = org AND id = p_key;
  PERFORM set_config('itap.client_key_context', 'off', true);
  RETURN QUERY SELECT * FROM itap.client_application_keys WHERE organization_id = org AND id = p_key;
END;
$$;
